def clean(df):
    df['Quantity'] = df['Quantity'].apply(lambda x: max(x, 0))
    df['Price'] = df['Price'].str.replace('$', '').astype(float)
    df['Region'] = df['Region'].str.lower().str.capitalize()
    df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    result = df.groupby('Category')['Revenue'].sum().to_dict()
    return result}
